    /**
     * Converts the key transpose table to actual key signatures.
     */
    private static func _translateKeyTransposeTable(_ texts: List<List<String>>) -> List<List<KeySignature>> {
        let keySignatures: List<List<KeySignature>> = List<List<KeySignature>>()
        for transpose in texts {
            let transposeValues: List<KeySignature> = List<KeySignature>()
            keySignatures.push(transposeValues)
            for keySignatureText in transpose {
                let keySignature: KeySignature = KeySignature.fromValue((Number.parseInt(keySignatureText.charAt(0.0), 10.0) * (keySignatureText.charAt(1.0) == "b" ? -1.0 : 1.0)))
                transposeValues.push(keySignature)
            }
        }
        return keySignatures
    }

