    /**
     * Transposes the given key signature.
     */
    internal static func transposeKey(_ keySignature: KeySignature, _ transpose: Double) -> KeySignature {
        if transpose == 0.0 {
            return keySignature
        }
        if transpose < 0 {
            let lookup: List<KeySignature> = ModelUtils._keyTransposeTable[(-transpose).toInt()]
            let keySignatureIndex: Double = lookup.indexOf(keySignature)
            if keySignatureIndex == -1.0 {
                return keySignature
            }
            return KeySignature.fromValue((keySignatureIndex - 7.0))
        } else {
            return ModelUtils._keyTransposeTable[(transpose).toInt()][(((Double(keySignature.rawValue))) + 7.0).toInt()]
        }
    }

    internal static func toArticulationId(_ plain: String) -> String {
        return plain.replace(TypeHelper.createRegex("[^a-zA-Z0-9]", "g"), "").lowercase()
    }

    public static func minBoundingBox(_ a: Double, _ b: Double) -> Double {
        if Number.isNaN(a) {
            return b
        } else if Number.isNaN(b) {
            return a
        }
        return a < b ? a : b
    }

    public static func maxBoundingBox(_ a: Double, _ b: Double) -> Double {
        if Number.isNaN(a) {
            return b
        } else if Number.isNaN(b) {
            return a
        }
        return a > b ? a : b
    }

    public static func getSystemLayout(_ score: Score, _ systemIndex: Double, _ displayedTracks: List<Track>) -> Double {
        var defaultSystemsLayout: Double
        var systemsLayout: List<Double>
        if displayedTracks.length == 1.0 {
            defaultSystemsLayout = displayedTracks[0].defaultSystemsLayout
            systemsLayout = displayedTracks[0].systemsLayout
        } else {
            defaultSystemsLayout = score.defaultSystemsLayout
            systemsLayout = score.systemsLayout
        }
        return systemIndex < systemsLayout.length ? systemsLayout[(systemIndex).toInt()] : defaultSystemsLayout
    }

